import React, { useState, useEffect } from 'react';
import Navbar from './components/Navbar';
import Hero from './components/Hero';
import Ticker from './components/Ticker';
import WhyMe from './components/WhyMe';
import Stats from './components/Stats';
import Services from './components/Services';
import Process from './components/Process';
import Projects from './components/Projects';
import Testimonials from './components/Testimonials';
import Contact from './components/Contact';
import Footer from './components/Footer';
import LoadingSkeleton from './components/LoadingSkeleton';
import { initAnimations, refreshScrollTrigger } from './utils/animations';
import './App.css';

export default function App() {
  const [isLoading, setIsLoading] = useState(true);

  useEffect(() => {
    // Show loading skeleton for 2.5 seconds
    const timer = setTimeout(() => {
      setIsLoading(false);
    }, 2500);

    return () => clearTimeout(timer);
  }, []);

  useEffect(() => {
    if (!isLoading) {
      // Initialize GSAP animations after loading is complete
      const timer = setTimeout(() => {
        initAnimations();
      }, 100);

      // Refresh ScrollTrigger on window resize
      const handleResize = () => {
        refreshScrollTrigger();
      };

      window.addEventListener('resize', handleResize);

      return () => {
        clearTimeout(timer);
        window.removeEventListener('resize', handleResize);
      };
    }
  }, [isLoading]);

  if (isLoading) {
    return <LoadingSkeleton />;
  }

  return (
    <div className="antialiased font-body text-base">
      <main className="bg-white">
        <div className="divide-y divide-black last:border-b">
          <Navbar />
          <Hero />
          <Ticker />
          <WhyMe />
          <Stats />
          <Services />
          <Process />
          <Projects />
          <Testimonials />
          <Contact />
        </div>
      </main>
      <Footer />
    </div>
  );
}
